def _wait(transport: Transport, failed_attempt: int, r: Response | None) -> None:
    seconds: float = 2 ** (failed_attempt - 1)
    if r is not None:
        for k, v in r.headers.items():
            if k.lower() == "retry-after":
                try:
                    seconds = int(str(v).strip())
                except ValueError:
                    pass
    transport.sleep(seconds)


def _attempt(transport: Transport, method: str, path: str, headers: dict[str, str], body: dict[str, Any] | None):
    """One request: returns (response, None) or (None, ConnectionError)."""
    try:
        return transport.send(method, path, dict(headers), body), None
    except ConnectionError as e:
        return None, e


def _retryable(r: Response) -> bool:
    if r.status in _RETRY_STATUS:
        return True
    return r.status == 409 and _error(r).code == "idempotency_in_progress"


def _call(transport: Transport, method: str, path: str, body: dict[str, Any] | None = None, key: str | None = None) -> Any:
    headers = {"Idempotency-Key": key} if key else {}
    for n in range(1, _MAX_ATTEMPTS + 1):
        r, exc = _attempt(transport, method, path, headers, body)
        if r is not None:
